    const fl = (i.flag||'').split(',').filter(Boolean);
    return fl.some(f => state.flags.has(f));
  });
  const [key,dir] = state.sort.split('-');
  const mult = dir === 'asc' ? 1 : -1;
  out = [...out].sort((a,b) => {
    if (key === 'owner') {
      const av = (a.owner || '').toLowerCase();
      const bv = (b.owner || '').toLowerCase();
      if (av === bv) return 0;
      if (!av) return 1;
      if (!bv) return -1;
      return av < bv ? -1 * mult : 1 * mult;
    }
    let av = key==='score'?a.score:key==='value'?a.value:(a.age_days??-1);
    let bv = key==='score'?b.score:key==='value'?b.value:(b.age_days??-1);
    return (av-bv)*mult;
  });
  return out;
}

